CHK='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#1652F0" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="flex-shrink: 0; margin-top: 2px"><path d="m5 12.5 4.5 4.5L19 7.5"></path></svg>'
def li(t): return '<li style="display: flex; gap: 10px; font-size: 14.5px; line-height: 1.45; color: #3A4566">'+CHK+'<span>'+t+'</span></li>'
GHOSTBTN='<a href="{href}" class="ob-ghost" style="margin-top: 12px; display: flex; align-items: center; justify-content: center; height: 52px; border-radius: 999px; border: 1.5px solid #D6DDEE; background: #FFFFFF; color: #0B1433; font-size: 15px; font-weight: 600; text-decoration: none">{label}</a>'
def tile(svg,bg='#EAF0FF',fg='#1652F0'): return '<div class="ob-in" style="width: 60px; height: 60px; border-radius: 18px; background: '+bg+'; color: '+fg+'; display: flex; align-items: center; justify-content: center; margin-bottom: clamp(16px, 3vh, 24px)">'+svg+'</div>'

