c = tile('<svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="3" width="16" height="18" rx="2"></rect><path d="M9 7h.01"></path><path d="M15 7h.01"></path><path d="M9 11h.01"></path><path d="M15 11h.01"></path><path d="M10 21v-4h4v4"></path></svg>')
